"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["55695"],{24421(e){e.exports=JSON.parse('{"id":"F323","slug":"commodity-roll-yield","name":"Commodity Futures: Basis and Roll Yield","subject":"Derivatives","section":"Derivatives","topic":"Commodity futures: contango and backwardation","level":"Intermediate","aliases":["contango","backwardation","roll return","futures curve"],"formula":{"latex":"\\\\text{Basis}=S-F,\\\\quad \\\\text{Roll yield per roll}=\\\\frac{F_{near}}{F_{far}}-1","also":[],"text":"Basis = Spot - Futures; Roll yield = Near futures price / Next futures price - 1 (negative in contango, positive in backwardation)"},"symbols":[{"symbol":"S","meaning":"Spot price","unit":"money"},{"symbol":"F_near","meaning":"Price of the near futures contract that is about to expire","unit":"money"},{"symbol":"F_far","meaning":"Price of the next contract that replaces it","unit":"money"}],"when_to_use":"Use it to see what rolling a futures position costs or earns. In contango (the futures curve slopes up) a long investor sells the cheaper near contract and buys the dearer far one, losing roll yield. In backwardation the curve slopes down and the long investor gains.","worked_example":{"problem":"Oil spot is 80, the near contract is 81.20 and the next contract (one month later) is 82.50. What is the roll yield, and what is it annualized?","inputs":{"s":80,"near":81.2,"far":82.5,"gap":1},"steps":[{"label":"Futures minus spot (positive means contango)","working":"81.2-80","value":"1.20"},{"label":"Roll yield per roll = near / far - 1","working":"81.2 / 82.5-1","value":"-1.58%"},{"label":"Annualized roll yield = (1 + roll yield)^(12 / months) - 1","working":"(1+-0.0157576)^(12 / 1)-1","value":"-17.35%"}],"answer":"The market is in contango, since futures trade above spot by 1.20. Rolling from the near to the next contract gives a roll yield of -1.58% each month, or about -17.35% a year, which reduces the return of a long position even if spot prices do not change."},"calculator":{"available":true,"inputs":[{"id":"s","label":"Spot price","unit":"money","type":"number","default":80,"hint":""},{"id":"near","label":"Near futures price","unit":"money","type":"number","default":81.2,"hint":""},{"id":"far","label":"Next futures price","unit":"money","type":"number","default":82.5,"hint":""},{"id":"gap","label":"Months between the contracts","unit":"number","type":"number","default":1,"hint":"","min":0.5}],"checks":[],"steps":[{"id":"carry","label":"Futures minus spot (positive means contango)","expr":"near-s","format":"money"},{"id":"ry","label":"Roll yield per roll = near / far - 1","expr":"near/far-1","format":"pct2"},{"id":"ann","label":"Annualized roll yield = (1 + roll yield)^(12 / months) - 1","expr":"(1+ry)^(12/gap)-1","format":"pct2"}],"results":["ry","ann"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"ry":-1.5757575757575748e-2,"ann":-0.1735340447801923}},"finder":{"finds":"The gain or cost of rolling commodity futures","needs":"Spot, near price, next price, months between contracts"},"related":[{"slug":"forward-price-cost-of-carry","name":"Futures Price: Cost of Carry"},{"slug":"cagr","name":"Compound Annual Growth Rate (CAGR)"}],"related_ids":["F319","F038"],"group":"Markets and instruments","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mtext>Basis</mtext><mo>=</mo><mi>S</mi><mo>\u2212</mo><mi>F</mi><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mtext>Roll\xa0yield\xa0per\xa0roll</mtext><mo>=</mo><mfrac><msub><mi>F</mi><mrow><mi>n</mi><mi>e</mi><mi>a</mi><mi>r</mi></mrow></msub><msub><mi>F</mi><mrow><mi>f</mi><mi>a</mi><mi>r</mi></mrow></msub></mfrac><mo>\u2212</mo><mn>1</mn></mrow><annotation encoding=\\"application/x-tex\\">\\\\text{Basis}=S-F,\\\\quad \\\\text{Roll yield per roll}=\\\\frac{F_{near}}{F_{far}}-1</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"commercial-paper-yield","name":"Commercial Paper Price and Yield"},"next":{"slug":"commodity-futures-total-return","name":"Commodity Futures: Roll Yield and Total Return"},"lesson":null,"total":522}')}}]);